class KeyPair:
    """
    A signing key + its public key, as raw bytes.

    PoC choice: the 32-byte Ed25519 seed is returned to the caller so the app can persist it in
    on-device storage and reconstruct the key to sign offline. A production build would keep the
    secret inside Rust behind an opaque handle backed by the platform keystore / secure element.
    """

    secret: "bytes"
    """
    32-byte Ed25519 signing seed (secret). Keep on device only.
    """

    public: "bytes"
    """
    32-byte Ed25519 public key — this is the account's `from`/`to` identity on the ledger.
    """

    def __init__(self, *, secret: "bytes", public: "bytes"):
        self.secret = secret
        self.public = public

    def __str__(self):
        return "KeyPair(secret={}, public={})".format(self.secret, self.public)

    def __eq__(self, other):
        if self.secret != other.secret:
            return False
        if self.public != other.public:
            return False
        return True

class _UniffiConverterTypeKeyPair(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        return KeyPair(
            secret=_UniffiConverterBytes.read(buf),
            public=_UniffiConverterBytes.read(buf),
        )

    @staticmethod
    def check_lower(value):
        _UniffiConverterBytes.check_lower(value.secret)
        _UniffiConverterBytes.check_lower(value.public)

    @staticmethod
    def write(value, buf):
        _UniffiConverterBytes.write(value.secret, buf)
        _UniffiConverterBytes.write(value.public, buf)


