# DpayError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class DpayError(Exception):
    """
    Errors crossing the FFI boundary. Each maps 1:1 to a `dpay_core` failure so the app can react
    (bad key length, malformed QR, a rejected authorization) without string-sniffing.
    """

    pass

_UniffiTempDpayError = DpayError

class DpayError:  # type: ignore
    """
    Errors crossing the FFI boundary. Each maps 1:1 to a `dpay_core` failure so the app can react
    (bad key length, malformed QR, a rejected authorization) without string-sniffing.
    """

    class BadSecretLength(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.BadSecretLength({})".format(str(self))
    _UniffiTempDpayError.BadSecretLength = BadSecretLength # type: ignore
    class BadPubkeyLength(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.BadPubkeyLength({})".format(str(self))
    _UniffiTempDpayError.BadPubkeyLength = BadPubkeyLength # type: ignore
    class BadNonceLength(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.BadNonceLength({})".format(str(self))
    _UniffiTempDpayError.BadNonceLength = BadNonceLength # type: ignore
    class BadBase64(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.BadBase64({})".format(str(self))
    _UniffiTempDpayError.BadBase64 = BadBase64 # type: ignore
    class BadWireLength(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.BadWireLength({})".format(str(self))
    _UniffiTempDpayError.BadWireLength = BadWireLength # type: ignore
    class PubkeyMismatch(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.PubkeyMismatch({})".format(str(self))
    _UniffiTempDpayError.PubkeyMismatch = PubkeyMismatch # type: ignore
    class BadInput(_UniffiTempDpayError):
        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "DpayError.BadInput({})".format(str(self))
    _UniffiTempDpayError.BadInput = BadInput # type: ignore
    class Amount(_UniffiTempDpayError):
        """
        A decimal amount string was rejected by `parse_amount`. Carries a debuggable code matching
        `dpay_core::AmountError` (`empty`/`not_a_number`/`negative`/`too_many_decimals`/`overflow`)
        so the app reacts without string-sniffing. MC1 unit 1.
        """

        def __init__(self, *values):
            if len(values) != 1:
                raise TypeError(f"Expected 1 arguments, found {len(values)}")
            if not isinstance(values[0], str):
                raise TypeError(f"unexpected type for tuple element 0 - expected 'str', got '{type(values[0])}'")
            super().__init__(", ".join(map(repr, values)))
            self._values = values

        def __getitem__(self, index):
            return self._values[index]

        def __repr__(self):
            return "DpayError.Amount({})".format(str(self))
    _UniffiTempDpayError.Amount = Amount # type: ignore
    class NfcWrongState(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.NfcWrongState({})".format(str(self))
    _UniffiTempDpayError.NfcWrongState = NfcWrongState # type: ignore
    class NfcNotDpay(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.NfcNotDpay({})".format(str(self))
    _UniffiTempDpayError.NfcNotDpay = NfcNotDpay # type: ignore
    class NfcProtocol(_UniffiTempDpayError):
        def __init__(self):
            pass

        def __repr__(self):
            return "DpayError.NfcProtocol({})".format(str(self))
    _UniffiTempDpayError.NfcProtocol = NfcProtocol # type: ignore

DpayError = _UniffiTempDpayError # type: ignore
del _UniffiTempDpayError


class _UniffiConverterTypeDpayError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return DpayError.BadSecretLength(
            )
        if variant == 2:
            return DpayError.BadPubkeyLength(
            )
        if variant == 3:
            return DpayError.BadNonceLength(
            )
        if variant == 4:
            return DpayError.BadBase64(
            )
        if variant == 5:
            return DpayError.BadWireLength(
            )
        if variant == 6:
            return DpayError.PubkeyMismatch(
            )
        if variant == 7:
            return DpayError.BadInput(
                _UniffiConverterString.read(buf),
            )
        if variant == 8:
            return DpayError.Amount(
                _UniffiConverterString.read(buf),
            )
        if variant == 9:
            return DpayError.NfcWrongState(
            )
        if variant == 10:
            return DpayError.NfcNotDpay(
            )
        if variant == 11:
            return DpayError.NfcProtocol(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, DpayError.BadSecretLength):
            return
        if isinstance(value, DpayError.BadPubkeyLength):
            return
        if isinstance(value, DpayError.BadNonceLength):
            return
        if isinstance(value, DpayError.BadBase64):
            return
        if isinstance(value, DpayError.BadWireLength):
            return
        if isinstance(value, DpayError.PubkeyMismatch):
            return
        if isinstance(value, DpayError.BadInput):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, DpayError.Amount):
            _UniffiConverterString.check_lower(value._values[0])
            return
        if isinstance(value, DpayError.NfcWrongState):
            return
        if isinstance(value, DpayError.NfcNotDpay):
            return
        if isinstance(value, DpayError.NfcProtocol):
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, DpayError.BadSecretLength):
            buf.write_i32(1)
        if isinstance(value, DpayError.BadPubkeyLength):
            buf.write_i32(2)
        if isinstance(value, DpayError.BadNonceLength):
            buf.write_i32(3)
        if isinstance(value, DpayError.BadBase64):
            buf.write_i32(4)
        if isinstance(value, DpayError.BadWireLength):
            buf.write_i32(5)
        if isinstance(value, DpayError.PubkeyMismatch):
            buf.write_i32(6)
        if isinstance(value, DpayError.BadInput):
            buf.write_i32(7)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, DpayError.Amount):
            buf.write_i32(8)
            _UniffiConverterString.write(value._values[0], buf)
        if isinstance(value, DpayError.NfcWrongState):
            buf.write_i32(9)
        if isinstance(value, DpayError.NfcNotDpay):
            buf.write_i32(10)
        if isinstance(value, DpayError.NfcProtocol):
            buf.write_i32(11)





class NfcPhase(enum.Enum):
    """
    Lifecycle phase of a tap, for a live UI status indicator. Mirrors [`dpay_core::nfc::SessionPhase`]
    (lifecycle only — failures surface as thrown `DpayError`s / a platform tag-loss, never as a
    phase). The app renders a spinner on `Linking`/`Exchanging`, a review prompt on
    `AwaitingApproval`, and then settles online after `Settling` / stops on `Declined`.
    """

    IDLE = 0
    
    LINKING = 1
    
    EXCHANGING = 2
    
    AWAITING_APPROVAL = 3
    
    SETTLING = 4
    """
    The bundle was transferred; the merchant is settling it before returning a signed result.
    """

    
    COMPLETE = 5
    """
    The payer verified the merchant-signed result.
    """

    
    DECLINED = 6
    


